<h1>Permessi raccolta — <?= e($collection['name']) ?></h1><p class="muted">Default: nessun utente/gruppo non owner vede i documenti. Admin: tutto; Editor: crea/modifica senza cancellare; Viewer: sola lettura.</p>
<form method="post" action="/collections/<?= (int)$collection['id'] ?>/acl/grant" class="card form-card acl-form"><?= \Archium\Support\Csrf::field() ?><h2>Aggiungi utenti o gruppi</h2><div class="subject-tabs"><label><input type="radio" name="subject_type" value="user" checked> Utenti</label><label><input type="radio" name="subject_type" value="group"> Gruppi</label></div><div class="acl-subjects" data-subject="user"><?php foreach($users as $user): ?><label class="checkbox-row"><input type="checkbox" name="subject_ids[]" value="<?= (int)$user['user_id'] ?>"><span><strong><?= e($user['name']) ?></strong><small><?= e($user['email']) ?> · ruolo workspace: <?= e($user['role']) ?></small></span></label><?php endforeach; ?></div><div class="acl-subjects hidden" data-subject="group"><?php foreach($groups as $group): ?><label class="checkbox-row"><input type="checkbox" name="subject_ids[]" value="<?= (int)$group['id'] ?>"><span><strong><?= e($group['name']) ?></strong><small><?= e($group['description']??'') ?> · <?= (int)$group['member_count'] ?> membri</small></span></label><?php endforeach; ?></div><label>Ruolo</label><select name="role"><option value="viewer">Viewer</option><option value="editor">Editore</option><option value="admin">Amministratore</option></select><button>Applica agli elementi selezionati</button></form>
<h2>Assegnazioni correnti</h2><?php if($entries===[]): ?><p class="muted">Nessun permesso esplicito.</p><?php else: ?><table class="card"><tr><th>Soggetto</th><th>Tipo</th><th>Dettaglio</th><th>Ruolo</th><th></th></tr><?php foreach($entries as $entry): ?><tr><td><?= e($entry['subject_name']) ?></td><td><?= e($entry['subject_type']==='user'?'Utente':'Gruppo') ?></td><td><?= e($entry['subject_detail']) ?></td><td><span class="badge ok"><?= e($entry['role']) ?></span></td><td><form method="post" action="/collections/<?= (int)$collection['id'] ?>/acl/<?= e($entry['subject_type']) ?>/<?= (int)$entry['subject_id'] ?>/revoke" class="inline-form"><?= \Archium\Support\Csrf::field() ?><button class="btn-sm danger">Rimuovi</button></form></td></tr><?php endforeach; ?></table><?php endif; ?><p><a href="/collections">Torna alle raccolte</a></p>